def solution(input_str):
    """
    Solves the microwave banana problem.

    Given n operations and m targets, find the earliest time-step for each target
    banana count j (1 to m).

    Each operation can be applied a_i times (0 <= a_i <= y_i):
    - Type 1: k := ceil(k + x_i) applied a_i times = ceil(k + a_i * x_i)
    - Type 2: k := ceil(k * x_i) applied a_i times = ceil(ceil(...ceil(k * x_i) * x_i)...)
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    ops = []
    for i in range(n):
        t, x_prime, y = map(int, lines[i + 1].split())
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # Reachable[v] = earliest time-step we can reach exactly v bananas
    # Initialize with 0 bananas at time step 0
    reachable = [-1] * (m + 1)
    reachable[0] = 0

    # Track all possible values we can reach considering different choices of a_i
    # For Type 1, we can reach v + a*x after ceil(v + a*x) operations (which is just v + a*x for integer v)
    # For Type 2, we can reach ceil(v * x) * x * x^(a-1) after multiple multiplications

    for i in range(n):  # i from 0 to n-1, representing time-step i+1
        t, x, y = ops[i]
        if t == 1:  # Type 1: k := ceil(k + x_i) applied a_i times
            for v in range(1, m + 1):
                if reachable[v] != -1:
                    # From v, we can apply Type 1 up to y times
                    # After a additions: k = ceil(v + a * x_i) 
                    # Since ceiling is involved, k = floor(v + a * x_i) + 1 when v + a*x_i is not integer
                    # Actually: ceil(v + a*x) for any a in [1, y]
                    for a in range(1, y + 1):
                        new_val = int((v + a * x + 0.9999999))  # Simulate ceil
                        if new_val <= m and reachable[new_val] == -1:
                            reachable[new_val] = i + 1
        else:  # Type 2: k := ceil(k * x_i) applied a_i times
            for v in range(1, m + 1):
                if reachable[v] != -1:
                    # After first multiplication: k' = ceil(v * x)
                    # After second: k'' = ceil(k' * x)
                    # etc.
                    k = int((v * x + 0.9999999))  # ceil(v * x)
                    for _ in range(y):
                        if k > m:
                            break
                        for a in range(1, y + 1):  # Multiple applications
                            k2 = int((k * x + 0.9999999))
                            if k2 > m:
                                break
                            if reachable[k2] == -1:
                                reachable[k2] = min(reachable[k2] if reachable[k2] != -1 else float('inf'), i + 1)
                            k = k2
                            break  # After one iteration, we continue to next opportunity

    # Build result array for 1 to m bananas
    result = []
    for j in range(1, m + 1):
        result.append(str(reachable[j]))

    return '\n' + ' '.join(result) + '\n'
