    a = list(map(int, lines[1].split()))

    def f(x):
        """Compute f(x): divide x by k repeatedly until not divisible"""
        while x % k == 0:
            x //= k
        return x

    found = [False]
    ops = []

    def search(nums):
        """Backtracking to find a sequence of operations that results in [1]"""
        nonlocal ops, found

        if found[0]:
            return

        if len(nums) == 1:
            if nums[0] == 1:
                found[0] = True
                return
            return

        # Try all unique pairs (force order to avoid duplicate work)
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if found[0]:
                    break

                x, y = nums[i], nums[j]
                z = f(x + y)

                # Build new list: remove x and y, add z
                new_nums = nums[:i] + [z] + nums[j+1:]

                ops.append((x, y))
                search(new_nums)
                ops.pop()

            if found[0]:
                break

    search(a)

    if found[0]:
        return "YES\n" + "\n".join(f"{x} {y}" for x, y in ops)
    return "NO"
