from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        edges.append((x, y, w, i + 1))
        adj[x].append((y, i + 1))
        adj[y].append((x, i + 1))

    def is_reachable(n, start, end, blocked):
        """Check if end is reachable from start after blocking edges in blocked set"""
        if start == end:
            return True

        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True

        while queue:
            u = queue.popleft()
            if u == end:
                return True

            for v, edge_id in adj[u]:
                if edge_id not in blocked and not visited[v]:
                    visited[v] = True
                    queue.append(v)

        return False

    # Case 0: Already disconnected (0 edges need to be removed)
    if not is_reachable(n, s, t, set()):
        return "0\n0\n"

    # Case 1: Try removing 1 edge
    min_cost = float('inf')
    best_single = None

    for _, _, w, edge_id in edges:
        if not is_reachable(n, s, t, {edge_id}):
            if w < min_cost:
                min_cost = w
                best_single = edge_id

    if min_cost != float('inf'):
        return f"{min_cost}\n1\n{best_single}"

    # Case 2: Try removing 2 edges
    min_cost = float('inf')
    best_pair = None

    # Get edges incident to s
    edges_at_s = []
    for _, _, w, edge_id in edges:
        if s == edges[0][0] or s == edges[0][1]:
            edges_at_s.append((w, edge_id))

    # Get edges incident to t
    edges_at_t = []
    for _, _, w, edge_id in edges:
        if t == edges[0][0] or t == edges[0][1]:
            edges_at_t.append((w, edge_id))

    # Try all pairs from s
    for i, (w1, id1) in enumerate(edges_at_s):
        for j, (w2, id2) in enumerate(edges_at_s):
            if i != j:
                blocked = {id1, id2}
                if not is_reachable(n, s, t, blocked):
                    cost = w1 + w2
                    if cost < min_cost:
