    def is_gp(a):
        """Check if a sequence is a geometric progression."""
        m = len(a)
        if m <= 2:
            return True  # Any sequence with 0 or 1 element is a GP

        # Check if all are zero
        if all(x == 0 for x in a):
            return True

        # If first two are both zero, all remaining must be zero
        if a[0] == 0 and a[1] == 0:
            return all(x == 0 for x in a[2:])

        # If one is zero and other isn't, it's not a valid GP
        if a[0] == 0 or a[1] == 0:
            return False

        # Calculate ratio from first two elements
        ratio = float(a[1]) / float(a[0])
        prev = float(a[0])

        for i in range(2, m):
            expected = prev * ratio
            if abs(float(a[i]) - expected) > 1e-7:
                return False
            prev = expected

        return True

    # Check if original array is a GP
    if is_gp(arr):
        return "0"

    # Try removing each element
    for i in range(n):
        temp = arr[:i] + arr[i+1:]
        if is_gp(temp):
            return "1"

    return "2"
