    stack_set = set()
    scc_id = [-1] * (n + 1)
    next_small_num = [0] * (n + 1)
    is_large = [False] * (n + 1)

    def tarjan():
        for start in range(1, n + 1):
            if visited[start]:
                continue
            visited[start] = True
            stack.append(start)
            stack_set.add(start)
            next_small_num[start] = 1
            ssc = start

            while stack:
                u = stack[-1]
                if next_small_num[u] == 1:
                    for v in rev_adj[u]:
                        if visited[v]:
                            if stack_set.intersection(rev_adj[u]):
                                is_large[u] = True
                        elif not visited[v]:
                            visited[v] = True
                            stack.append(v)
                            stack_set.add(v)
                            next_small_num[v] = 1
                            ssc = v
                    next_small_num[u] += 1
                else:
                    stack.pop()
                    stack_set.discard(u)
                    if scc_id[u] == -1:
