import math

def solution(input_str):
    n, m, k = map(int, input_str.strip().split())

    # If m (20 euro banknotes) is 0, Charlie always succeeds
    if m == 0:
        return "1\n"

    # If n < m - k and k < m, then 20 euro people exceed what can be covered
    # Specifically, we need at least m - k people with 10 euros to start with change

    # Total arrangements: C(n + m, m)
    def combinations(n, r):
        if r < 0 or r > n:
            return 0
        return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))

    total = combinations(n + m, m)

    if m > n + k:
        # If there are too many 20 euro people, we can never have change
        return "0\n"

    # Use the generalized ballot theorem
    # Number of invalid paths = paths staying above diagonal y = x + k
    # Using reflection principle: C(n + m, m - n - k) if m >= n + k

    if k >= m - n:
        # Charlie starts with enough 10 euro notes to handle any worse case
        # Count using inclusion-exclusion or reflection principle
        invalid = 0
        for i in range(k + 1, m + 1):
            if i <= n and i >= 0:
                invalid += combinations(n + m, m - i)

        # More elegant approach using reflection
        # Valid = total - invalid
        # Invalid paths touch or cross the boundary y = x + k

        valid = ways(n, m, k)
    else:
        valid = ways(n, m, k)

    result = valid / total if total > 0 else 0
    return f"{result:.12f}\n"

def ways(n, m, k):
    """Calculate number of valid arrangements"""
    if m > n + k:
        return 0

    if k >= m - n:
        # If we start with enough change, all arrangements might be valid
        # Actually need to check using Catalan-like counting
        return total_paths(n, m)

    # Using reflection principle for generalized Catalan numbers
    # Number of valid paths = C(n+m, n) - C(n+m, n-k-1) for standard case
    # Generalized: We need k + i >= y where i is count of 10s, y is count of 20s

    total_paths = comb(n + m, n)

    # Count invalid paths using reflection principle
    invalid_paths = 0
    if n + k + 1 <= n + m:
        invalid_paths = comb(n + m, n - k - 1)

    return max(0, total_paths - invalid_paths)

def comb(n, r):
    if r < 0 or r > n:
        return 0
    result = 1
    for i in range(r):
        result = result * (n - i) // (i + 1)
    return result


