def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return ''

    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        a, b, e = map(int, lines[1 + i].split())
        edges.append((a - 1, b - 1, e, i))

    if m == n - 1:
        return ''

    # Sort edges by weight for Kruskal's algorithm
    sorted_edges = sorted(edges, key=lambda x: x[2])

    # Kruskal's algorithm to build MST
    parent = list(range(n))
    rank = [0] * n

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        pi, pj = find(i), find(j)
        if pi == pj:
            return False
        if rank[pi] < rank[pj]:
            pi, pj = pj, pi
        parent[pj] = pi
        if rank[pi] == rank[pj]:
            rank[pi] += 1
        return True

    mst_adj = [[] for _ in range(n)]
    mst_set = set()

    for u, v, w, idx in sorted_edges:
        if union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
            mst_set.add(idx)

    # Build LCA structure with binary lifting
    LOG = max(1, n.bit_length())
    depth = [0] * n
    node_parent = [i for i in range(n)]
    edge_to_parent = [0] * n

    # Iterative DFS to build parent and depth information
    stack = [(0, -1, 0)]  # (node, parent, depth)

    while stack:
        u, p, d = stack.pop()
        depth[u] = d
        node_parent[u] = p
        edge_to_parent[u] = 0

        for v, w in mst_adj[u]:
            if v != p:
                edge_to_parent[v] = w
                stack.append((v, u, d + 1))

    # Build binary lifting table
    up = [[i for i in range(n)] for _ in range(LOG)]
    max_ew = [[0] * LOG for _ in range(n)]

    for u in range(n):
        up[0][u] = node_parent[u]
        max_ew[0][u] = edge_to_parent[u]

    for j in range(1, LOG):
        for u in range(n):
            if up[j - 1][u] != -1:
                up[j][u] = up[j - 1][up[j - 1][u]]
                max_ew[j][u] = max(max_ew[j - 1][u], max_ew[j - 1][up[j - 1][u]])
            else:
                up[j][u] = -1
                max_ew[j][u] = max_ew[j - 1][u]

    def query_max(u, v):
        if u == v:
            return 0

        if depth[u] < depth[v]:
            u, v = v, u

        result = 0
        diff = depth[u] - depth[v]

        for j in range(LOG):
            if (diff >> j) & 1:
                result = max(result, max_ew[j][u])
                u = up[j][u]

        if u == v:
            return result

        for j in range(LOG - 1, -1, -1):
            if up[j][u] != up[j][v]:
                result = max(result, max_ew[j][u])
                result = max(result, max_ew[j][v])
                u = up[j][u]
                v = up[j][v]

        result = max(result, max_ew[0][u])
        return result

    # Process non-MST edges
    results = []
    for u, v, w, idx in edges:
        if idx not in mst_set:
            max_on_path = query_max(u, v)
            results.append(str(max_on_path))

    return '\n'.join(results)
