def check_axis_square(matrix, n, m, r, c, k):
    for i in range(k):
        if matrix[r + i][c] != '1':
            return False
        if matrix[r + i][c + k - 1] != '1':
            return False

    for j in range(k - 2):
        if matrix[r][c + j + 1] != '1':
            return False
        if matrix[r + k - 1][c + j + 1] != '1':
            return False

    for rr in range(r - 1, r + k + 1):
        for cc in range(c - 1, c + k + 1):
            if 0 <= rr < n and 0 <= cc < m:
                if (rr == r and cc == c) or (rr == r and cc == c + k - 1) or \
                   (rr == r + k - 1 and cc == c) or (rr == r + k - 1 and cc == c + k - 1):
                    continue
                if matrix[rr][cc] == '1':
                    return False

    if k > 2:
        for i in range(1, k - 1):
            for j in range(1, k - 1):
                if matrix[r + i][c + j] == '0':
                    return False
    elif k == 2:
        if matrix[r + 1][c + 1] == '0':
            return False

    return True


def check_diagonal_square(matrix, n, m, r_center, c_center, radius):
    if matrix[r_center][c_center] != '1':
        return False
    if matrix[r_center - 1][c_center] != '1':
        return False
    if matrix[r_center + 1][c_center] != '1':
        return False
    if matrix[r_center][c_center - 1] != '1':
        return False
    if matrix[r_center][c_center + 1] != '1':
        return False

    for rr in range(r_center - radius - 1, r_center + radius):
        for cc in range(c_center - radius - 1, c_center + radius + 1):
            if 0 <= rr < n and 0 <= cc < m:
                dist = abs(rr - r_center) + abs(cc - c_center)
                if dist < radius:
                    if matrix[rr][cc] == '0':
                        return False
                elif dist == radius:
                    if matrix[rr][cc] == '0':
                        return False
                else:
                    if matrix[rr][cc] == '1':
                        return False

    if radius == 1:
        return True
    else:
        if matrix[r_center][c_center] == '0':
            return False
        return True


def clear_square(matrix, n, m, r, c, k):
    for i in range(k):
        matrix[r + i][c] = '0'
        matrix[r + i][c + k - 1] = '0'

    if k > 2:
        for j in range(1, k - 1):
            matrix[r][c + j] = '0'
            matrix[r + k - 1][c + j] = '0'
    else:
        matrix[r + 1][c + 1] = '0'


def clear_diagonal_square(matrix, n, m, r, c, radius):
