import math

def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())
    l, r = map(int, lines[1].split())

    results = []

    # Precompute valid products to speed up
    valid_products = set()
    for p in range(l, r + 1):
        if p > n * m:
            break
        valid_products.add(p)

    # Precompute divisors for each possible product
    divisors = {}
    for p in valid_products:
        divisors[p] = []
        for i in range(1, int(math.isqrt(p)) + 1):
            if p % i == 0:
                divisors[p].append(i)
                if i != p // i:
                    divisors[p].append(p // i)

    # For each x1, find a valid tuple
    for x1 in range(1, n + 1):
        found = False
        # We need to find y1 such that x1*y1 is in [l, r], 
        # and there exists x2 > x1, y2 < y1 with x1*y1 = x2*y2

        # The product must be a multiple of x1
        min_y1 = (l + x1 - 1) // x1  # ceil(l / x1)
        max_y1 = min(m, r // x1)       # floor(r / x1)

        if min_y1 > max_y1:
            results.append("-1")
            continue

        for y1 in range(min_y1, max_y1 + 1):
            product = x1 * y1
            if product not in valid_products:
                continue

            # Try to find x2 > x1 that divides product and gives y2 < y1
            for d in divisors[product]:
                if d > x1 and d <= n:
                    y2 = product // d
                    if 1 <= y2 < y1:
                        found = True
                        results.append(f"{x1} {y1} {d} {y2}")
                        break

            if found:
                break
        else:
            results.append("-1")

    return '\n'.join(results)
