    for i in range(n):
        root = find(i)
        components[root].append(i)

    # For each component, determine if it can go to A, B, or both
    component_assignment = {}
    possible = True

    for root, indices in components.items():
        can_go_to_A = True
        for idx in indices:
            val = p[idx]
            if (a - val) in val_to_idx:
                other = val_to_idx[a - val]
                if find(other) != root:
                    can_go_to_A = False
                    break

        can_go_to_B = True
        for idx in indices:
            val = p[idx]
            if (b - val) in val_to_idx:
                other = val_to_idx[b - val]
                if find(other) != root:
                    can_go_to_B = False
                    break

        if can_go_to_A:
            component_assignment[root] = 0
        else:
            if can_go_to_B:
                component_assignment[root] = 1
            else:
                possible = False
                break

    if not possible:
        return "NO\n"

    # Build result
    result = []
    for i in range(n):
        root = find(i)
        if root in component_assignment:
            if component_assignment[root] == 0:
                result.append('0')
            else:
                result.append('1')
        else:
            return "NO\n"

    return "YES\n" + " ".join(result) + "\n"
