from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())
    clauses = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        k = int(parts[0])
        literals = [int(x) for x in parts[1:]]
        clauses.append(literals)

    num_nodes = 2 * m + 2
    adj = [[] for _ in range(num_nodes)]

    def lit_to_node(l):
        if l > 0:
            return 2 * l
        else:
            return 2 * (-l) - 1

    def not_node(l):
        return lit_to_node(-l)

    for clause in clauses:
        if len(clause) == 1:
            l = clause[0]
            adj[not_node(l)].append(lit_to_node(l))
        else:
            for i in range(len(clause) - 1):
                adj[not_node(clause[i])].append(lit_to_node(clause[i + 1]))
                adj[not_node(clause[i + 1])].append(lit_to_node(clause[i]))

    ids = [-1] * num_nodes
    low = [-1] * num_nodes
    on_stack = [False] * num_nodes
    stack = []
    scc_id = [-1] * num_nodes
    scc_cnt = 0
    timer = 0

    def dfs(u):
        nonlocal timer
        stack.append(u)
        on_stack[u] = True
        ids[u] = low[u] = timer
        timer += 1

        for v in adj[u]:
            if ids[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if ids[u] == low[u]:
            while True:
                node = stack.pop()
                on_stack[node] = False
                scc_id[node] = scc_cnt
                if node == u:
                    break
            scc_cnt += 1

    for i in range(num_nodes):
        if ids[i] == -1:
            dfs(i)

    for i in range(1, m + 1):
        if scc_id[2 * i - 1] == scc_id[2 * i]:
            return "NO"

    result = ""
    for i in range(1, m + 1):
        if scc_id[2 * i - 1] > scc_id[2 * i]:
            result += "1"
        else:
            result += "0"

    return "YES\n" + result


