def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    if N == 1 and M == 1:
        return '0\n'

    # Parse all transformers
    transformers = []
    for i in range(1, K+1):
        parts = lines[i].split()
        if len(parts) >= 5:
            x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
            transformers.append((x, y, d, t, e))

    if not transformers:
        return '0\n'

    # Build map: (position, time) -> list of (transformer_id, energy)
    pt_transformers = {}

    for idx, (x, y, d, t_start, e) in enumerate(transformers):
        for offset in range(4):
            curr_time = t_start + offset

            # Handle wrapping for y when d > position
            # Pattern follows: (x,y) -> (x+d,y-d) -> (x+d,y) -> (x,y+d)
            if offset == 0:
                rx, ry = x, y
            elif offset == 1:
                rx, ry = x + d, y - d
            elif offset == 2:
                rx, ry = x + d, y
            elif offset == 3:
                rx, ry = x, y + d

            if 0 <= rx < N and 0 <= ry < M:
                pt = (rx, ry, curr_time)
                if pt not in pt_transformers:
                    pt_transformers[pt] = []
                pt_transformers[pt].append((idx, e))

    # DP: dp[r][c] = minimum energy to reach (r,c)
    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]
    dp[0][0] = 0

    # Process by time step (r+c)
    for time_step in range(1, N + M - 1):
        for r in range(max(0, time_step - (M - 1)), min(N - 1, time_step) + 1):
            c = time_step - r
            if 0 <= c < M and 0 <= r < N:
                # Calculate min dp[r][c] from predecessors
                prev_cost = INF
                if r > 0 and dp[r-1][c] != INF:
                    prev_cost = min(prev_cost, dp[r-1][c])
                if c > 0 and dp[r][c-1] != INF:
                    prev_cost = min(prev_cost, dp[r][c-1])

                if prev_cost == INF:
                    continue

                # Add cost of transformers at this position and time
                # Only add if this is the first time we encounter this (r,c,time) state
                cost = prev_cost

                if (r, c, time_step) in pt_transformers:
                    cost += sum(e for _, e in pt_transformers[(r, c, time_step)])

                dp[r][c] = cost

    return str(int(dp[N-1][M-1]) if dp[N-1][M-1] != INF else 0) + '\n'
