import sys

MOD = 10**9 + 7

def count_digits_up_to(n):
    """Count total digits in numbers from 1 to n."""
    if n <= 0:
        return 0
    total = 0
    for length in range(1, 15):
        lo = 10**(length-1)
        hi = min(n, 10**length - 1)
        if lo <= hi:
            total += (hi - lo + 1) * length
    return total

def concat_range_value(l, r):
    """Compute concatenated value from l to r modulo MOD, and total length."""
    if l > r:
        return 0, 0

    total_len = count_digits_up_to(r) - count_digits_up_to(l - 1)
    result = 0
    for num in range(l, r + 1):
        digit_len = len(str(num))
        result = (result * pow(10, digit_len, MOD) + num) % MOD
    return result, total_len

def repeat_value(k, val, length):
    """Repeat val, k times and return new value mod MOD and new length."""
    if k == 0:
        return 0, 0
    if k == 1:
        return val % MOD, length

    pow_ = pow(10, length, MOD)
    if pow_ == 1:
        return val * k % MOD, length * k

    pow_k = pow(pow_, k - 1, MOD)
    numerator = (pow_k - 1 + MOD) % MOD
    denominator = (pow_ - 1 + MOD) % MOD
    denominator_inv = pow(denominator, MOD - 2, MOD)
    series_sum = numerator * denominator_inv % MOD
    result = val * series_sum % MOD
    return result, length * k

def solve(expr):
    expr = expr.strip()
    n = len(expr)
    pos = 0

    def parse_term():
        nonlocal pos

        result = None

        # Check for range pattern: number-number
        if pos < n and expr[pos].isdigit():
            start1 = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            l = int(expr[start1:pos])

            if pos < n and expr[pos] == '-':
                pos += 1  # consume '-'
                start2 = pos
                while pos < n and expr[pos].isdigit():
                    pos += 1
                r = int(expr[start2:pos])
                result = concat_range_value(l, r)

        # Check for repeat pattern: number(...)
        if result is None and pos < n and expr[pos].isdigit():
            start_num = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            k = int(expr[start_num:pos])

            if pos < n and expr[pos] == '(':
                pos += 1  # consume '('
                inner = parse_expr_list()
                if inner is None:
                    return None, None

                if pos < n and expr[pos] == ')':
                    pos += 1  # consume ')'

                result = repeat_value(k, inner[0], inner[1])

        # Check for simple number
        if result is None and pos < n and expr[pos].isdigit():
            start = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            val = int(expr[start:pos]) % MOD
            result = (val % MOD, pos - start)

        return result

    def parse_expr_list():
        nonlocal pos

        result = parse_term()
        if result is None:
            return None

        while pos < n and expr[pos] == '+':
            pos += 1  # consume '+'
            term = parse_term()
            if term is None:
